Ltac qfb3_fin := match goal with K : forall (m' : mem) (t1' t2' : word), _ |- _ =>
  eapply K; try eassumption; try (intros; congruence) end.

(* [comment removed for export] *)
Lemma merge_fb3 : forall (P : machine_state -> Prop) ra sp gp tp t1 t2 s0 s1 a2 a5 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11
    t3 t4 t5 t6 (F : bvmap 5 word) fc (m : mem) (FROM TO n0 f0 l0 B0 b b' nb' sz cnt xn xf xl xb : Z),
  (0 < FROM)%Z -> (FROM + 32 <= TO \/ TO + 32 <= FROM)%Z ->
  (b + 8192 <= b' \/ b' + 8192 <= b)%Z -> (0 < b /\ b + 8192 <= 2^47)%Z -> (0 < b' /\ b' + 8192 <= 2^47)%Z ->
  (FROM + 32 <= b \/ b + 8192 <= FROM)%Z -> (FROM + 32 <= b' \/ b' + 8192 <= FROM)%Z ->
  (TO + 32 <= b \/ b + 8192 <= TO)%Z -> (TO + 32 <= b' \/ b' + 8192 <= TO)%Z -> (0 <= TO /\ TO + 32 <= 2^64)%Z ->
  (2 <= n0 < 2^63)%Z -> (0 <= l0 < 2^64)%Z -> (0 <= nb' < 2^64)%Z -> (0 <= xn < 2^63)%Z ->
  (xn <> 0 -> (0 < xl /\ xl + 8192 <= 2^47) /\ (xl + 8192 <= b \/ b + 8192 <= xl) /\ (xl + 8192 <= b' \/ b' + 8192 <= xl)
              /\ (FROM + 32 <= xl \/ xl + 8192 <= FROM) /\ (TO + 32 <= xl \/ xl + 8192 <= TO))%Z ->
  rw_cells asegs m FROM [C8 (Z_to_bv 64 n0); C8 (Z_to_bv 64 f0); C8 (Z_to_bv 64 l0); C8 (Z_to_bv 64 B0)] ->
  rw_cells asegs m TO [C8 (Z_to_bv 64 xn); C8 (Z_to_bv 64 xf); C8 (Z_to_bv 64 xl); C8 (Z_to_bv 64 xb)] ->
  rw_cells asegs m b [C8 (Z_to_bv 64 b'); C8 (Z_to_bv 64 sz); C8 (Z_to_bv 64 cnt)] ->
  rw_cells asegs m b' [C8 (Z_to_bv 64 nb'); C8 (Z_to_bv 64 8192); C8 (Z_to_bv 64 0)] ->
  (xn <> 0 -> rw_cells asegs m xl [C8 (Z_to_bv 64 0); C8 (Z_to_bv 64 8192); C8 (Z_to_bv 64 0)])%Z ->
  mem_inv asegs m ->
  (forall (m' : mem) (t1' t2' : word),
     munch [(FROM, FROM + 32); (TO, TO + 32); (b, b + 8); (b', b' + 8); (if xn =? 0 then b' else xl, (if xn =? 0 then b' else xl) + 8)]%Z
       m m' -> wmono asegs m m' -> mem_inv asegs m' ->
     rw_cells asegs m' FROM [C8 (Z_to_bv 64 (n0 - 1)); C8 (Z_to_bv 64 f0); C8 (Z_to_bv 64 (if l0 =? b' then b else l0));
                             C8 (Z_to_bv 64 B0)] ->
     rw_cells asegs m' TO [C8 (Z_to_bv 64 xn); C8 (Z_to_bv 64 (if xn =? 0 then b' else xf)); C8 (Z_to_bv 64 xl); C8 (Z_to_bv 64 xb)] ->
     rw_cells asegs m' b [C8 (Z_to_bv 64 nb'); C8 (Z_to_bv 64 sz); C8 (Z_to_bv 64 cnt)] ->
     rw_cells asegs m' b' [C8 (Z_to_bv 64 0); C8 (Z_to_bv 64 8192); C8 (Z_to_bv 64 0)] ->
     (xn <> 0 -> rw_cells asegs m' xl [C8 (Z_to_bv 64 b'); C8 (Z_to_bv 64 8192); C8 (Z_to_bv 64 0)])%Z ->
     evt asegs P (MS (mkR ra sp gp tp (Z_to_bv 64 b') t1' t2' s0 s1 (Z_to_bv 64 FROM) (Z_to_bv 64 TO) a2 (Z_to_bv 64 (xn + 1))
                          (Z_to_bv 64 b) a5 (Z_to_bv 64 (-8192)) (Z_to_bv 64 8192) s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                     F (Z_to_bv 64 0xa2f14) fc None m' (seg_rom asegs))) ->
  evt asegs P (MS (mkR ra sp gp tp (Z_to_bv 64 b') t1 t2 s0 s1 (Z_to_bv 64 FROM) (Z_to_bv 64 TO) a2 (Z_to_bv 64 n0)
                       (Z_to_bv 64 b) a5 (Z_to_bv 64 (-8192)) (Z_to_bv 64 8192) s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
