(* [comment removed for export] *)
Lemma merge_fb4 : forall (P : machine_state -> Prop) ra sp gp tp t1 t2 s0 s1 a5 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11
    t3 t4 t5 t6 (F : bvmap 5 word) fc (m : mem) (FROM TO ax b b' nb' sz cnt xn xf xl xb : Z),
  (0 <= TO /\ TO + 32 <= 2^64)%Z -> (0 < b /\ b + 8192 <= 2^47)%Z -> (TO + 32 <= b \/ b + 8192 <= TO)%Z ->
  rw_cells asegs m TO [C8 (Z_to_bv 64 xn); C8 (Z_to_bv 64 xf); C8 (Z_to_bv 64 xl); C8 (Z_to_bv 64 xb)] ->
  rw_cells asegs m b [C8 (Z_to_bv 64 nb'); C8 (Z_to_bv 64 sz); C8 (Z_to_bv 64 cnt)] ->
  mem_inv asegs m ->
  (forall (m' : mem),
     munch [(TO, TO + 32)]%Z m m' -> wmono asegs m m' -> mem_inv asegs m' ->
     rw_cells asegs m' TO [C8 (Z_to_bv 64 (xn + 1)); C8 (Z_to_bv 64 xf); C8 (Z_to_bv 64 b'); C8 (Z_to_bv 64 (xb + 8192))] ->
     rw_cells asegs m' b [C8 (Z_to_bv 64 nb'); C8 (Z_to_bv 64 sz); C8 (Z_to_bv 64 cnt)] ->
     evt asegs P (MS (mkR ra sp gp tp (Z_to_bv 64 nb') t1 t2 s0 s1 (Z_to_bv 64 FROM) (Z_to_bv 64 TO) (Z_to_bv 64 (ax + 8192))
                          (Z_to_bv 64 (xb + 8192)) (Z_to_bv 64 b) a5 (Z_to_bv 64 (-8192)) (Z_to_bv 64 8192)
                          s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                     F (Z_to_bv 64 0xa2f30) fc None m' (seg_rom asegs))) ->
  evt asegs P (MS (mkR ra sp gp tp (Z_to_bv 64 b') t1 t2 s0 s1 (Z_to_bv 64 FROM) (Z_to_bv 64 TO) (Z_to_bv 64 ax) (Z_to_bv 64 (xn + 1))
                       (Z_to_bv 64 b) a5 (Z_to_bv 64 (-8192)) (Z_to_bv 64 8192) s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
